import { cleanCase } from './domain.js';

const quote = input => JSON.stringify(String(input)) ;

export function slugify(input) {
  return String(input).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 70) || 'qa-case';
}

/** Generate Playwright test using semantic, stable data-testid locators. */
export function generateSpec(input) {
  const testcase = cleanCase(input, input.id ? input : null);
  const lines = [
    '// Generated by TraceProof QA. Review assertions before using in CI.',
    "import { test, expect } from '@playwright/test';",
    '',
    `test(${quote(testcase.title)}, async ({ page }) => {`
  ];
  for (const step of testcase.steps) {
    const selector = step.target ? `page.getByTestId(${quote(step.target)})` : '';
    switch (step.action) {
      case 'navigate': lines.push(`  await page.goto(${quote(step.value)});`); break;
      case 'click': lines.push(`  await ${selector}.click();`); break;
      case 'fill': lines.push(`  await ${selector}.fill(${quote(step.value)});`); break;
      case 'assertVisible': lines.push(`  await expect(${selector}).toBeVisible();`); break;
      case 'assertText': lines.push(`  await expect(${selector}).toContainText(${quote(step.value)});`); break;
    }
  }
  lines.push('});', '');
  return lines.join('\n');
}

export function outputFilename(item) { return `${slugify(item.title)}.spec.ts`; }
